      "rank": 1,
      "ballot_id": "B021",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have transformed precision measurement, enabling unprecedented tests of fundamental physics and new forms of sensing. This is a major experimental achievement with broad influence.",
        "attribution": "Katori and Ye made complementary foundational contributions to the clock concept and its experimental realization.",
        "maturity": "The clocks have been demonstrated and steadily improved over decades; their accuracy and reproducibility are exceptionally well established.",
        "uncertainties": [
          "The relative attribution between the original clock concept, key technical advances, and later implementations deserves careful consideration."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how fragile quantum states can be protected in principle, making scalable quantum information processing a physically meaningful goal. Its influence reaches well beyond computing into quantum communication and sensing.",
        "attribution": "Kitaev, Steane, and Shor each made landmark contributions to the theory of fault tolerance and error-correcting codes.",
        "maturity": "The principles are established and have been experimentally tested in increasingly capable systems, though large-scale fault-tolerant operation remains an active challenge.",
        "uncertainties": [
          "The field's continuing development makes it difficult to separate the foundational contributions from later advances in practical fault tolerance."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Juan Ignacio Cirac",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattices made strongly interacting quantum matter controllable in the laboratory and opened a powerful route to studying many-body physics. The combination of precise experiments and theoretical guidance has had a lasting impact.",
        "attribution": "Bloch and Greiner led defining experimental demonstrations, while Cirac and Zoller helped establish the quantum simulation framework and its theoretical foundations.",
        "maturity": "The platform has produced a long record of reproducible results and continues to develop as a tool for studying difficult many-body problems.",
        "uncertainties": [
          "The discovery is a sustained program with many contributors, so a three-person prize limit would make attribution difficult."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B025",
      "proposed_laureates": [
        "Claudio Pellegrini",
        "Jörg Rossbach",
        "Kwang-Je Kim"
      ],
      "assessment": {
        "nobel_worthiness": "X-ray free-electron lasers created a new way to observe matter on ultrafast timescales and at atomic length scales. Their impact as instruments for studying physical, chemical, and biological systems is substantial.",
        "attribution": "Pellegrini, Rossbach, and Kim are associated with crucial accelerator and FEL concepts and development, but the achievement spans large teams and multiple facilities.",
        "maturity": "Operational facilities have delivered influential results for years, and the capability is experimentally well established.",
        "uncertainties": [
          "The proposed names may not capture the full international and technical contributions needed to make these facilities work."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions provided a clear and experimentally controlled route to quantum logic, linking foundational proposals to high-fidelity demonstrations. This work helped establish quantum information as an experimental physics field.",
        "attribution": "Cirac and Zoller developed the influential ion-trap quantum-computing proposal, and Blatt's experiments demonstrated its central ideas with exceptional control.",
        "maturity": "Ion-trap operations are reproducible and well characterized, although general-purpose fault-tolerant machines remain under development.",
        "uncertainties": [
          "The contributions overlap with broader atomic quantum information and simulation work, complicating the boundary of the discovery."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B046",
      "proposed_laureates": [
        "Franz J. Giessibl",
        "Gerhard Meyer",
        "Leo Gross"
      ],
      "assessment": {
        "nobel_worthiness": "qPlus force microscopy enabled atomic-resolution imaging and spectroscopy of surfaces with a highly sensitive mechanical probe. It is a powerful measurement method that has exposed local structure and interactions inaccessible to earlier techniques.",
        "attribution": "Giessibl developed the qPlus sensor approach, with Meyer and Gross contributing important instrumental advances and demonstrations.",
        "maturity": "The method has been used broadly and refined over many years, with extensive experimental confirmation.",
        "uncertainties": [
          "Its standing relative to other scanning-probe microscopy advances and the division of credit for subsequent capabilities need careful assessment."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B018",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mark Saffman",
        "Mikhail D. Lukin",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Programmable Rydberg arrays offer remarkable control over interacting atoms and have opened a new experimental route to quantum simulation and information processing.",
        "attribution": "Browaeys, Saffman, and Lukin have led major experimental programs, while Zoller contributed foundational theory for neutral-atom quantum computing.",
        "maturity": "The platform has advanced rapidly and produced strong demonstrations, but its long-term scientific and practical impact is still emerging.",
        "uncertainties": [
          "The field is young, and a four-name attribution is difficult to reconcile with the prize's usual limits."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Artur Ekert",
        "Charles H. Bennett",
        "Gilles Brassard"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum key distribution established that quantum principles can support communication protocols with security rooted in physical laws. It stimulated major work in quantum information and communication.",
        "attribution": "Bennett and Brassard introduced a landmark protocol, and Ekert developed an influential entanglement-based approach.",
        "maturity": "The principles have been experimentally demonstrated and implemented in increasingly capable systems, though a global network with practical scale and reliability remains a developing goal.",
        "uncertainties": [
          "The ballot also includes global quantum networks and later demonstrations, whose contributions extend beyond these foundational protocols."
        ]
      }
    }
  ]
